//! Zig wrapper over ncnn's C API.
//!
//! Owning wrappers are explicit resources. Use `deinit` exactly once, `move`
//! to transfer ownership, and `clone` when an independent copy is required.
//! Copying an owning wrapper by value does not retain the underlying C handle.

/// Raw C API generated by translate-c.
///
/// Prefer the wrappers below; use this for anything not wrapped yet.
pub const c = @import("ncnn_c");

pub const errors = @import("errors.zig");
pub const version = @import("version.zig");
pub const mat = @import("mat.zig");
pub const option = @import("option.zig");
pub const net = @import("net.zig");
pub const paramdict = @import("paramdict.zig");
pub const pixel = @import("pixel.zig");
pub const draw = @import("draw.zig");
pub const layer = @import("layer.zig");
pub const datareader = @import("datareader.zig");
pub const modelbin = @import("modelbin.zig");
pub const allocator = @import("allocator.zig");

pub const Error = errors.Error;

/// N-dimensional tensor.
pub const Mat = mat.Mat;

/// Inference settings.
pub const Option = option.Option;

/// Loaded network.
pub const Net = net.Net;

/// Runs one inference pass over a net.
pub const Extractor = net.Extractor;

/// Layer parameter bag.
pub const ParamDict = paramdict.ParamDict;

/// Custom layer handle.
pub const Layer = layer.Layer;

/// Model data source.
pub const DataReader = datareader.DataReader;

/// Weight reader for custom layers.
pub const ModelBin = modelbin.ModelBin;

/// Pool allocator for blob and workspace memory.
pub const Allocator = allocator.Allocator;

/// Verifies the header version matches the linked runtime.
pub const checkVersion = version.check;
